"""Original expanded practice and linked-step challenges for Weeks 6–10.
Every numerical answer is checked exactly before export.
"""
from fractions import Fraction as F
from decimal import Decimal as D
import json, math, statistics, re
from pathlib import Path
DAYS=['Sat','Sun','Mon','Tue','Wed','Thu','Fri']
SPACING_MAP=json.loads(Path('work/expanded_spacing_map.json').read_text())

def clean(obj):
 if isinstance(obj,dict):return {k:(v if k in ['check','skill','kind','solid','id'] else clean(v)) for k,v in obj.items()}
 if isinstance(obj,list):return [clean(v) for v in obj]
 if isinstance(obj,str):
  obj=re.sub(r'[A-Za-z]{5,}',lambda m:SPACING_MAP.get(m.group(),m.group()),obj)
  obj=re.sub(r'(?<=[a-z])(?=[A-Z])',' ',obj)
  obj=re.sub(r'(?<=[A-Za-z])(?=[$])',' ',obj)
  obj=re.sub(r'([A-Za-z]{2,})([0-9])',r'\1 \2',obj)
  obj=re.sub(r'([0-9])([A-Za-z]{2,})',r'\1 \2',obj)
  obj=re.sub(r'\b([A-Za-z]{2,})\(',r'\1 (',obj)
  obj=re.sub(r'(\))([a-z]{1,3})\b',r'\1 \2',obj)
  obj=re.sub(r'([A-Za-z]{2,})(?=[−+|{])',r'\1 ',obj)
  obj=re.sub(r'([;,:])(?=\S)',r'\1 ',obj)
  obj=re.sub(r'(?<![0-9])\.(?=[A-Za-z])','. ',obj)
  return obj
 return obj


def fmt(x):
 x=F(x)
 return str(x.numerator) if x.denominator==1 else '{'+str(x.numerator)+'/'+str(x.denominator)+'}'
def lit(x):
 x=F(x);return f'F({x.numerator},{x.denominator})'
def q(text,answer,worked,skill,check,**kw):
 assert eval(check,{'F':F,'D':D,'math':math,'statistics':statistics}), (text,answer,check)
 return dict(text=text,answer=str(answer),worked=worked,skill=skill,check=check,**kw)
def c(text,answer,worked,skill,check,ask,hint,visual_hint=''):
 return q(text,answer,worked,skill,check,challenge=True,discussion={'ask':ask,'expect':answer,'if_stuck':hint},visual_hint=visual_hint)

