def spiral(seed,count):
 out=[];a=seed%7+2;b=seed%5+3
 out.append(q(f'A ribbon is{a} m long. Each bow uses{{{b}/4}} m. How many complete bows can be made, and what ribbon remains?',f'{(4*a)//b} bows;{fmt(F(a)-((4*a)//b)*F(b,4))} m remains.',f'Compute{a}÷{fmt(F(b,4))}={fmt(F(4*a,b))}. Use only the whole-number quotient for complete bows; subtract the ribbon used.','F-DIV',f'divmod(F({a}),F({b},4))==({(4*a)//b},{lit(F(a)-((4*a)//b)*F(b,4))})'))
 x=F(a,4);y=F(b,6)
 out.append(q(f'Find{fmt(x)} + {fmt(y)}. Give an estimate first.',fmt(x+y),f'Rename in twelfths:{fmt(x)}={3*a}/12 and{fmt(y)}={2*b}/12; add and simplify.','F-ADD',f'{lit(x)}+{lit(y)}=={lit(x+y)}'))
 out.append(q(f'{a} sketchbooks cost${a*b}. What do{a+3} sketchbooks cost at the same price?',f'${(a+3)*b}',f'Each costs${b}; multiply by{a+3}.','R-RATE',f'F({a*b},{a})*{a+3}=={(a+3)*b}'))
 whole=20*(a+1);p=5*b
 out.append(q(f'A club has{whole} members;{p}% walk to meetings. How many walk?',str(whole*p//100),f'Find{p}/100 of{whole}: divide by100, then multiply by{p}.','P-PART',f'F({p},100)*{whole}=={whole*p//100}'))
 x=F(10*a+b,10);y=F(b,4)
 out.append(q(f'Find{float(x):g} × {float(y):g}. Explain whether the product exceeds{float(x):g}.',f'{fmt(x*y)}; '+('greater' if y>1 else 'equal' if y==1 else 'less'),f'Multiply exactly; the second factor is{fmt(y)}, which is '+('greater than1.' if y>1 else 'equal to1.' if y==1 else 'less than1.'),'D-MULT',f'{lit(x)}*{lit(y)}=={lit(x*y)} and ({lit(x*y)}>{lit(x)})==({lit(y)}>1)'))
 out.append(q(f'A rectangle measures{a} cm by{b} cm. Find its area and perimeter.',f'{a*b} square cm;{2*(a+b)} cm.',f'Area multiplies the sides; perimeter adds two of each side.','G-AREA',f'({a}*{b},2*({a}+{b}))==({a*b},{2*(a+b)})'))
 out.append(q(f'Find the GCF and LCM of{2*a} and{3*a}. Describe one use for each.',f'GCF{a};LCM{6*a}.',f'The greatest shared factor is{a}; the first shared positive multiple is{6*a}. GCF can make equal groups; LCM can match repeating events.','N-GCFLCM',f'math.gcd({2*a},{3*a})=={a} and math.lcm({2*a},{3*a})=={6*a}'))
 out.append(q(f'A box is{a} cm by{b} cm by2 cm. Find its volume.',f'{2*a*b} cubic cm.',f'There are{a*b} unit cubes in one layer and2 layers.','G-VOL',f'{a}*{b}*2=={2*a*b}'))
 x=F(a+1,3);y=F(b,5)
 out.append(q(f'Compare{fmt(x)} and{fmt(y)} using<,=,or>. Show equivalent fractions.',f'{fmt(x)} '+('>' if x>y else '<' if x<y else '=')+f' {fmt(y)}.',f'Use denominator15: numerators are{5*(a+1)} and{3*b}.','F-COMP',f'({lit(x)}>{lit(y)})=={x>y} and ({lit(x)}<{lit(y)})=={x<y}'))
 out.append(q(f'{a*b} beads are split in the ratio1:{b-1}. Find both parts.',f'{a} and{a*(b-1)} beads.',f'There are{b} equal ratio units; each contains{a} beads.','R-WHOLE',f'F({a*b},1+{b-1})=={a} and {a}+{a*(b-1)}=={a*b}'))
 x=F(3*a,10);y=F(3,10)
 out.append(q(f'Find{float(x):g} ÷0.3. Check by multiplication.',str(a),f'Scale both numbers by10:{3*a}÷3={a}. Then{a}×0.3={float(x):g}.','D-DIV',f'{lit(x)}/{lit(y)}=={a} and {a}*{lit(y)}=={lit(x)}'))
 return out[:count]

def algebra_practice(di):
 a=di+3;b=di%4+2;n=di+2;out=[]
 out.append(q(f'A packet contains{a} cards. Write the number in p packets plus{b} loose cards; evaluate at p={n}.',f'{a}p+{b};{a*n+b} cards.',f'Multiply cards per packet by the packet count, then add loose cards.','E-EXPR',f'{a}*{n}+{b}=={a*n+b}'))
 out.append(q(f'Evaluate{b}t+{a} when t={n}. Show the multiplication first.',str(b*n+a),f'{b}×{n}+{a}={b*n}+{a}={b*n+a}.','E-EVAL',f'{b}*{n}+{a}=={b*n+a}'))
 out.append(q(f'Evaluate{b}²+{a}. Explain what the exponent means.',str(b*b+a),f'The exponent gives two equal factors:{b}×{b}; add{a} afterward.','E-EXP',f'{b}**2+{a}=={b*b+a}'))
 out.append(q(f'Expand{b}(x+{a}) and check at x={n}.',f'{b}x+{a*b};both equal{b*(n+a)}.',f'Multiply both x and{a} by{b}.','E-DIST',f'{b}*({n}+{a})=={b}*{n}+{a*b}=={b*(n+a)}'))
 out.append(q(f'Simplify{a}y+{b}y+y. Evaluate at y=2.',f'{a+b+1}y;{2*(a+b+1)}.',f'Add the counts of equal y terms:{a}+{b}+1={a+b+1}.','E-LIKE',f'{a}*2+{b}*2+2=={a+b+1}*2=={2*(a+b+1)}'))
 out.append(q(f'A rectangle has height{b} and width z+{a}. Write its area two ways.',f'{b}(z+{a})={b}z+{a*b}.',f'Split the rectangle into widths z and{a}; their areas add.','E-DIST',f'all({b}*(z+{a})=={b}*z+{a*b} for z in [1,3,7])'))
 out.append(q(f'Solve x+{a}={a+n}. Show a change to both sides.',f'x={n}.',f'Subtract{a} from each side, then check by addition.','E-ADD',f'{a+n}-{a}=={n} and {n}+{a}=={a+n}'))
 out.append(q(f'Solve{b}x={b*n}. Check using multiplication.',f'x={n}.',f'Divide both sides by{b}; each of{b} equal groups is{n}.','E-MULT',f'F({b*n},{b})=={n} and {b}*{n}=={b*n}'))
 out.append(q(f'Solve{{{b}/{b+1}}}x={b*n}. Draw{b+1} equal parts.',f'x={(b+1)*n}.',f'The{b} known parts total{b*n}, so one part is{n}. All{b+1} parts total{(b+1)*n}.','E-MULT',f'F({b},{b+1})*{(b+1)*n}=={b*n}'))
 out.append(q(f'{a} identical pens cost${a*b}. Write and solve an equation for price p per pen.',f'{a}p={a*b};p=${b}.',f'Divide the whole cost among{a} equal pen prices.','E-STORY',f'F({a*b},{a})=={b}'))
 out.append(q(f'Use y={b}x+{a} for x=0,1,3. Give the ordered pairs.',f'(0,{a}),(1,{a+b}),(3,{a+3*b}).',f'Substitute each input, multiply by{b}, and add{a}.','E-RELATE',f'[{b}*x+{a} for x in [0,1,3]]==[{a},{a+b},{a+3*b}]'))
 out.append(q(f'Are{b}(u+{a}) and{b}u+{a} equivalent? Test u=2 and repair the second expression.','No;'+f'{b}u+{a*b} is equivalent.',f'The first gives{b*(2+a)}; the second gives{2*b+a}. The constant must also be multiplied by{b}.','E-DIST',f'{b}*(2+{a})!={b}*2+{a} and {b}*(2+{a})=={b}*2+{a*b}'))
 return out

