def make_week6():
 days=[]
 for di,day in enumerate(DAYS):
  core=algebra_practice(di)
  if day=='Sat':practice=core[:6]
  elif day=='Sun':practice=core[6:]
  else:practice=core+spiral(60+di,11 if day=='Wed' else 6)
  days.append(dict(weekday=day,challenges=C[6][day],practice=practice,estimated_minutes=80 if day=='Sat' else 80 if day=='Sun' else 55 if day=='Wed' else 45))
 return clean(dict(week=6,days=days,sessions=DEEP[6]))


