 out.append(q(f'A parallelogram has base{a} cm,height{b} cm,and slanted side{b+2} cm. Find area and name the unused length.',f'{a*b} square cm;slanted side{b+2} cm unused.',f'The height is perpendicular to the base;use{a}×{b}.','G-PARA',f'{a}*{b}=={a*b}'))
 out.append(q(f'A right triangle has perpendicular legs{2*a} cm and{b} cm. Find area using either leg as base.',f'{a*b} square cm.',f'One half of the product of the perpendicular legs is{a*b}.','G-TRI',f'F({2*a}*{b},2)==F({b}*{2*a},2)=={a*b}'))
 out.append(q(f'A triangle has area{a*b} square cm and base{2*a} cm. Find its matching height.',f'{b} cm.',f'Double the area,then divide by the base:{2*a*b}÷{2*a}={b}.','G-TRI',f'F(2*{a*b},{2*a})=={b}'))
 out.append(q(f'A{a+3} cm by{b+2} cm rectangle loses a3 cm by2 cm corner. Find remaining area.',f'{(a+3)*(b+2)-6} square cm.','Subtract the six-square-centimeter cutout from the whole rectangle.','G-COMP',f'({a+3})*({b+2})-3*2=={(a+3)*(b+2)-6}'))
 out.append(q(f'A triangle and parallelogram share base{a} and height{b}. Find each area and their ratio.',f'Triangle{fmt(F(a*b,2))};parallelogram{a*b};ratio1:2.',f'The triangle uses one half of the same base-height product.','G-TRI',f'F({a*b},2)/{a*b}==F(1,2)'))
 out.append(q(f'A closed box measures2 cm by{b} cm by{a} cm. Find surface area.',f'{2*(2*b+2*a+a*b)} square cm.',f'Add two faces of each kind:2×{2*b}+2×{2*a}+2×{a*b}.','G-SA',f'2*(2*{b}+2*{a}+{b}*{a})=={2*(2*b+2*a+a*b)}'))
 out.append(q(f'A cube has side{b} cm. Find surface area and volume;label units.',f'{6*b*b} square cm;{b**3} cubic cm.',f'Six square faces give6×{b}²;{b}layers of{b}² cubes give{b}³.','G-SA',f'(6*{b}**2,{b}**3)==({6*b*b},{b**3})'))
 out.append(q(f'A square pyramid has base side{2*b} cm and triangular face height{a} cm. Find surface area.',f'{(2*b)**2+4*a*b} square cm.',f'Base area{(2*b)**2};each of four triangles has area{a*b}. Add all five faces.','G-SA',f'{2*b}**2+4*F({2*b}*{a},2)=={(2*b)**2+4*a*b}'))
 out.append(q(f'A prism has3-4-5 right-triangle ends and length{a} cm. Find its surface area.',f'{12+12*a} square cm.',f'Two ends total12;three side rectangles total(3+4+5)×{a}.','G-SA',f'2*F(3*4,2)+(3+4+5)*{a}=={12+12*a}'))
 out.append(q(f'An open-top box has bottom{a} cm by{b} cm and height2 cm. Find material area,including the bottom.',f'{a*b+4*a+4*b} square cm.',f'One bottom has area{a*b};two long sides total{4*a};two short sides total{4*b}.','G-SA',f'{a}*{b}+2*{a}*2+2*{b}*2=={a*b+4*a+4*b}'))
 out.append(q(f'A closed2 by{b} by{a} box calculation omits one2-by{b} face. How much must be added? Give the corrected total.',f'Add{2*b};correcttotal{2*(2*b+2*a+a*b)} square cm.',f'The missing face area is2×{b};a complete net has six faces.','G-SA',f'2*{b}=={2*b} and 2*(2*{b}+2*{a}+{b}*{a})=={2*(2*b+2*a+a*b)}'))
