def signed_practice(di):
 a=di+3;b=di%4+2;out=[]
 out.append(q(f'Write signed numbers for{a} meters below sea level and{b} meters above it. State what zero represents.',f'−{a},+{b};sea level.','Below the reference is negative;above is positive.','N-CONTEXT',f'-{a}<0<{b}'))
