def build_all():
 result=[make_week6()]
 funcs={7:geometry_practice,8:signed_practice,9:stats_practice,10:scale_practice}
 for wk in range(7,11):
  days=[]
  for di,day in enumerate(DAYS):
   pool=funcs[wk](di)
   if day=='Sat':practice=pool[:6]
   elif day=='Sun':practice=pool[6:14] if wk==9 else pool[6:12]
   else:practice=pool[:12]+spiral(wk*10+di,11 if day=='Wed' else 6)
   days.append(dict(weekday=day,challenges=C[wk][day],practice=practice,estimated_minutes=80 if day in ['Sat','Sun'] else 55 if day=='Wed' else 45))
  result.append(dict(week=wk,days=days,sessions=DEEP[wk]))
 for w in result:
  for ss in w['sessions']:
   assert eval(ss['deepening']['check'],{'F':F,'D':D,'math':math,'statistics':statistics}),ss['session']
   ss['deepening'].setdefault('minutes',8)
  for d in w['days']:
   assert len(d['challenges'])==2
   assert len(d['practice']) >= (23 if d['weekday']=='Wed' else 18 if d['weekday'] not in ['Sat','Sun'] else 6)
   assert len(set(p['text'] for p in d['practice']+d['challenges']))==len(d['practice'])+2
 return result


